import { vi } from "vitest";
import { runInNewContext } from "node:vm";
import { H3, HTTPError, type H3Event } from "../src/index.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("errors", (t, { it, expect, describe }) => {
  const consoleMock = ((globalThis.console.error as any) = vi.fn());

  describe("error response bodies", () => {
    for (const withOnError of [false, true]) {
      const hook = withOnError ? "with onError" : "without onError";

      it(`omits the body for a missing HEAD route ${hook}`, async () => {
        if (!withOnError) t.app.config.onError = undefined;
        const res = await t.fetch("/missing", { method: "HEAD" });
        expect(res.status).toBe(404);
        // A HEAD body is not rendered, so no (mismatching) content-length is advertised
        expect(res.headers.get("content-length")).toBeNull();
        expect(await res.text()).toBe("");
        expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
        expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
      });

      for (const asyncHandler of [false, true]) {
        for (const method of ["GET", "HEAD"]) {
          it(`renders ${method} errors from a ${asyncHandler ? "async" : "sync"} handler ${hook}`, async () => {
            if (!withOnError) t.app.config.onError = undefined;
            const handler = (event: H3Event) => {
              event.res.headers.set("x-success", "success");
              event.res.errHeaders.set("x-error", "prepared");
              event.res.errHeaders.append("set-cookie", "prepared=1");
              throw new HTTPError({
                status: 422,
                statusText: "Unprocessable",
                data: { test: 123 },
                headers: { "x-error-own": "own", "set-cookie": "error=1" },
              });
            };
            t.app.use(asyncHandler ? async (event) => handler(event) : handler);

            const res = await t.fetch("/", { method });
            expect(res.status).toBe(422);
            expect(res.statusText).toBe("Unprocessable");
            expect(res.headers.get("content-type")).toBe("application/json;charset=UTF-8");
            expect(res.headers.get("x-error")).toBe("prepared");
            expect(res.headers.get("x-error-own")).toBe("own");
            expect(res.headers.get("x-success")).toBeNull();
            expect(res.headers.getSetCookie()).toEqual(["error=1", "prepared=1"]);
            if (method === "HEAD") {
              expect(res.headers.get("content-length")).toBeNull();
              expect(await res.text()).toBe("");
            } else {
              expect(await res.json()).toMatchObject({
                status: 422,
                statusText: "Unprocessable",
                data: { test: 123 },
              });
            }
            expect(t.hooks.onError).toHaveBeenCalledTimes(withOnError ? 1 : 0);
            expect(t.hooks.onResponse).toHaveBeenCalledTimes(1);
import type { Mock } from "vitest";
import type { H3Config, H3Event, NodeHandler, HTTPError } from "../src/index.ts";
import { tracingPlugin } from "../src/tracing.ts";
import { Server as NodeServer } from "node:http";
import { getRandomPort } from "get-port-please";
import { beforeEach, afterEach, vi, it, describe, expect, beforeAll, afterAll } from "vitest";
import { H3 } from "../src/index.ts";
import { toNodeHandler } from "../src/_entries/node.ts";

// Matrix
export function describeMatrix(
  title: string,
  fn: (ctx: TestContext, testUtils: TestUtils) => void | Promise<void>,
  opts?: TestOptions,
): void {
  const run = (ctx: TestContext) => {
    const utils: TestUtils = {
      expect,
      describe,
      it: Object.assign(interceptFnWithSuffix(it, ctx.target), {
        only: interceptFnWithSuffix(it.only, ctx.target),
        todo: interceptFnWithSuffix(it.todo, ctx.target),
        skip: interceptFnWithSuffix(it.skip, ctx.target),
        skipIf: (condition: boolean) => (condition ? utils.it.skip : utils.it),
        runIf: (condition: boolean) => (condition ? utils.it : utils.it.skip),
      }),
    };
    fn(ctx, utils);
  };
  describe(title, () => {
    describe("web", () => {
      run(setupWebTest(opts));
    });
    describe("node", () => {
      run(setupNodeTest(opts));
    });
  });
}

// Web
function setupWebTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("web", opts);
  beforeEach(() => {
    ctx.fetch = (input, init) => {
      const headers = new Headers(init?.headers);
      if (input.startsWith("/") && !headers.has("host") && !headers.has("x-forwarded-host")) {
        headers.set("Host", "localhost");
      }
      return Promise.resolve(
        ctx.app.request(input, {
          ...init,
          headers,
        }),
      );
    };
  });
  return ctx;
}

// Node.js
function setupNodeTest(opts: TestOptions = {}): TestContext {
  const ctx = setupBaseTest("node", opts);

  let server: NodeServer;
  let handler: NodeHandler;

  beforeAll(async () => {
    server = new NodeServer((req, res) => {
      handler!(req, res);
    });
    const port = await getRandomPort();
    await new Promise<void>((resolve) => server.listen(port, resolve));
    ctx.url = `http://localhost:${port}`;
    ctx.fetch = (input, init = {}) => {
      const url = new URL(input, ctx.url);
      const headers = new Headers(init.headers);
      // Emulate a reverse proxy
      if (!headers.has("host")) {
        headers.set("Host", url.host);
      }

