        this.all(`${base}/**`, function _mountedMiddleware(event) {
          if (hasEmptySegmentAfterBase(event.url.pathname, base)) {
            throw new HTTPError({ status: 404 });
          }
          return fetchHandler(requestWithBaseURL(event.req, base, { url: event.url }));
        });
      }
      return this;
    }

